// Why Code: arma una tabla HTML con un renglón por cita (bucle + escape HTML); el nodo HTML no permite iterar filas con estilos por renglón.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $input.first().json;
const dias = ['', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];
const citas = Array.isArray(d.citas) ? d.citas : JSON.parse(d.citas || '[]');
const total = Number(d.total) || 0;
const celda = 'padding:10px 14px;font-size:14px;color:#555;';
const filas = citas.map((c, i) => `<tr style="background:${i % 2 ? '#f8f9fa' : '#ffffff'}">`
  + `<td style="${celda}font-weight:bold;color:#1a73e8;white-space:nowrap;">${esc(c.hora_inicio)} - ${esc(c.hora_fin)}</td>`
  + `<td style="${celda}">${esc(c.nombre)} ${esc(c.apellido)}</td><td style="${celda}">${esc(c.cedula)}</td>`
  + `<td style="${celda}">${esc(c.telefono)}</td><td style="${celda}">${esc(c.area)}</td><td style="${celda}">${esc(c.descripcion)}</td></tr>`).join('');
const vacio = '<tr><td colspan="6" style="padding:30px;text-align:center;color:#888;">No hay citas programadas para hoy.</td></tr>';
const th = (t) => `<th style="padding:10px 14px;text-align:left;font-size:12px;color:#555;">${t}</th>`;
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="font-family:Arial,sans-serif;max-width:800px;margin:0 auto;padding:20px;background:#f5f5f5;">'
  + `<div style="background:#1a73e8;padding:20px 28px;"><div style="color:white;font-size:20px;font-weight:bold;">MYF Consultoría</div><div style="color:#c8d8f8;font-size:13px;margin-top:3px;">Agenda del día — ${dias[d.dia_semana]} ${d.fecha}</div></div>`
  + '<div style="background:white;border:1px solid #e0e0e0;border-top:none;padding:24px 28px;">'
  + `<p style="font-size:15px;color:#333;"><b style="font-size:26px;color:#1a73e8;">${total}</b> cita${total === 1 ? '' : 's'} pendiente${total === 1 ? '' : 's'} para hoy</p>`
  + '<table cellspacing="0" cellpadding="0" style="width:100%;border-collapse:collapse;border:1px solid #e0e0e0;">'
  + `<thead><tr style="background:#f1f3f4;">${th('Horario')}${th('Cliente')}${th('Cédula')}${th('Teléfono')}${th('Área')}${th('Descripción')}</tr></thead>`
  + `<tbody>${filas || vacio}</tbody></table>`
  + '<p style="color:#999;font-size:11px;margin-top:20px;">Generado automáticamente a las 07:00 hs. — MYF Consultoría</p></div></body></html>';
return [{ json: { html, total, asunto: `📋 Agenda del día — ${dias[d.dia_semana]} ${d.fecha} (${total} cita${total === 1 ? '' : 's'})` } }];
